package profile

import (
	"encoding/base64"
	"os"
	"strings"
	"testing"
)

func TestKaringDecryptionOpenSSLFixture(t *testing.T) {
	// Independently generated by openssl enc -aes-128-cbc with MD5(password), IV 00..0f.
	fixture, err := os.ReadFile("testdata/karing-subscription.txt")
	if err != nil {
		t.Fatal(err)
	}
	plain, err := DecryptSubscription(string(fixture), "decrypt-secret")
	if err != nil {
		t.Fatal(err)
	}
	nodes, err := ParseImport(plain)
	if err != nil || len(nodes) != 2 || nodes[0].Name != "HK" || nodes[1].Server != "example.net" {
		t.Fatal("known ciphertext failed", err)
	}
	if _, err := DecryptSubscription(string(fixture), "wrong"); err == nil {
		t.Fatal("wrong password accepted")
	}
	if _, err := DecryptSubscription(string(fixture), ""); err == nil {
		t.Fatal("missing password accepted")
	}
	raw, _ := DecodeBase64(strings.TrimSpace(string(fixture)))
	raw[len(raw)-1] ^= 1
	for _, bad := range []string{"!invalid", "", base64.StdEncoding.EncodeToString(raw), base64.StdEncoding.EncodeToString(raw[:17]), strings.Repeat("x", MaxSubscription+1)} {
		if _, err := DecryptSubscription(bad, "decrypt-secret"); err == nil {
			t.Fatal("malformed content accepted")
		}
	}
}
